    val owner=LocalLifecycleOwner.current;DisposableEffect(owner){val observer=LifecycleEventObserver{_,event->if(event==Lifecycle.Event.ON_RESUME)vm.refreshAuditAllocation()};owner.lifecycle.addObserver(observer);onDispose{owner.lifecycle.removeObserver(observer)}}
    LaunchedEffect(Unit){if(vm.githubConfigured())vm.loadRepos();vm.loadHistory()}
    val selected=repos.firstOrNull{it.fullName==selectedName};if(manifest&&scope!=null)ScopeDialog(scope!!,vm){manifest=false};historyItem?.let{HistoryDialog(it,{vm.deleteHistory(it.id);historyItem=null}){historyItem=null}}
    val running=run.stage in listOf(RepoAuditStage.SNAPSHOT,RepoAuditStage.INDEPENDENT,RepoAuditStage.PEER_REVIEW,RepoAuditStage.VERIFY,RepoAuditStage.CHAIRMAN);val notificationLauncher=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){}
    Scaffold(topBar={TopAppBar(title={Column{Text("Repository Audit",fontWeight=FontWeight.Bold);Text("OmniCouncil · v${BuildConfig.VERSION_NAME}",style=MaterialTheme.typography.labelSmall)}},navigationIcon={IconButton(onClick=onBack){Icon(Icons.Default.ArrowBack,"Back")}},actions={IconButton(onClick={tokenPanel=!tokenPanel}){Icon(Icons.Default.Key,"GitHub")};IconButton(onClick={outputPanel=!outputPanel}){Icon(Icons.Default.Folder,"Output")}})}){padding->
        LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
            if(tokenPanel)item{GitHubCard(vm,token,{token=it},{token="";tokenPanel=false})};if(outputPanel)item{OutputCard(vm,onChooseFolder)};message?.let{item{NoticeCard(it,vm::clearMessage)}}
