            if(mode=="run"){
                if(run.repoFullName.isNotBlank()){item{ProgressCard(run,vm)};if(run.modelAudits.isNotEmpty())item{EvidenceCard(run,vm)};if(run.peerReviews.isNotEmpty())item{PeerCard(run,vm)};if(run.verificationMemo.isNotBlank())item{LongTextCard("Verification",run.verificationMemo)};if(run.finalReport.isNotBlank())item{LongTextCard("Final report · ${vm.modelLabel(run.chairmanModel)}",run.finalReport)}}
                if(history.isNotEmpty()){item{Text("Previous completed audits",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold)};items(history,key={it.id}){h->ElevatedCard(Modifier.fillMaxWidth().clickable{historyItem=h}){ListItem(headlineContent={Text(h.repoFullName,fontWeight=FontWeight.SemiBold)},supportingContent={Text("${h.commitSha.take(10)} · ${h.requiredFiles} files · ${DateFormat.getDateTimeInstance().format(Date(h.finishedAt))}")},leadingContent={Icon(Icons.Default.History,null)},trailingContent={Icon(Icons.Default.ChevronRight,null)})}}}
            }else if(!running){
